from datetime import datetime
# Filter inbox threads from roommates
candidates = []
for t in found_inbox:
    participant_emails = {p.get('email') for p in t.get('participants', []) if p.get('email')}
    if participant_emails.intersection(roommate_emails):
        candidates.append(t)
print('candidates_in_inbox', len(candidates))
# Sort by created_at desc

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return datetime.min

candidates_sorted = sorted(candidates, key=lambda x: parse_dt(x.get('created_at')), reverse=True)
print('top5_thread_ids_created_at')
for t in candidates_sorted[:5]:
    print(t['email_thread_id'], t.get('subject'), t.get('created_at'), 'participants', [p['email'] for p in t.get('participants', [])])

# Search archived threads for electricity_bill.pdf attachments
from datetime import datetime
page_index = 0
page_limit = 20
found_archived = []
while True:
    threads = apis.gmail.show_archived_threads(access_token=gmail_access_token, query='electricity_bill.pdf', attachment=True, page_index=page_index, page_limit=page_limit)
    print('archived page', page_index, 'threads', len(threads))
    if not threads:
        break
    found_archived.extend(threads)
    if len(threads) < page_limit:
        break
    page_index += 1
print('total_archived_threads', len(found_archived))

roommate_emails = set(roommate_emails)
# Filter those that include roommates
candidates_archived = []
for t in found_archived:
    participant_emails = {p.get('email') for p in t.get('participants', []) if p.get('email')}
    if participant_emails.intersection(roommate_emails):
        candidates_archived.append(t)
print('candidates_archived', len(candidates_archived))

# show top5 by created_at

