    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return datetime.min

candidates_archived_sorted = sorted(candidates_archived, key=lambda x: parse_dt(x.get('created_at')), reverse=True)
